async fn require_auth(
    State(verifier): State<Arc<Verifier>>,            // delegated mechanism
    mut req: Request, next: Next,
) -> Result<Response, StatusCode> {
    let token = bearer(req.headers()).ok_or(StatusCode::UNAUTHORIZED)?;
    let principal = verifier.verify(token).map_err(|_| StatusCode::UNAUTHORIZED)?;
    req.extensions_mut().insert(principal);           // request-scoped
    Ok(next.run(req).await)
}
